SAB = "Sabiston Tratado de Cirugía 21.ª ed."
HAR = "Harrison Principios de Medicina Interna 21.ª ed. (2022)"
ACGP = "Tenner S, et al. ACG Guidelines: Management of Acute Pancreatitis. Am J Gastroenterol 2024;119:419-437"
ATL = "Banks PA, et al. Classification of acute pancreatitis 2012: revision of the Atlanta classification. Gut 2013;62:102-111"
